input.content:
// Sector colors
const sectorColors = {
    'Information Technology': '#3498db',
    'Industry': '#2ecc71',
    'Energy': '#e74c3c',
    'Financial': '#9b59b6',
    'ETF': '#95a5a6'
};

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return 'N/A';
    const num = parseFloat(value);
    if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
    return num.toLocaleString();
}

// Main visualization
async function init() {
    // Load data
    const data = await d3.csv('data/stock-descriptions.csv');

    // Process data
    const stocks = data.map(d => ({
        ticker: d.ticker,
        sector: d.sector,
        name: d['full name'],
        marketCap: parseFloat(d.marketCap) || 0,
        country: d.country || '',
        website: d.website || '',
        isETF: d.sector === 'ETF'
    }));

    // State for selection
    let selectedTicker = null;

    // Create tooltip
    const tooltip = d3.select('body')
        .append('div')
        .attr('class', 'tooltip');

    // Create bubble chart
    createBubbleChart(stocks, tooltip, (ticker) => {
        selectedTicker = ticker;
        updateSelection(ticker);
    });

    // Create table
    createTable(stocks, (ticker) => {
        selectedTicker = ticker;
        updateSelection(ticker);
    });

    // Create legend
    createLegend();

    function updateSelection(ticker) {
        // Update bubbles
        d3.selectAll('.bubble')
            .classed('selected', d => d.ticker === ticker);

        // Update table rows
        d3.selectAll('#stock-table tbody tr')
            .classed('selected', function() {
                return d3.select(this).attr('data-ticker') === ticker;
            });

        // Scroll table row into view
        const selectedRow = document.querySelector(`#stock-table tbody tr[data-ticker="${ticker}"]`);
        if (selectedRow) {
            selectedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    }
}

function createBubbleChart(stocks, tooltip, onSelect) {
    const container = document.getElementById('bubble-chart');
    const width = container.clientWidth;
    const height = 600;

    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    // Get unique sectors and their center positions
    const sectors = [...new Set(stocks.map(d => d.sector))];
    const sectorCenters = {};
    const cols = 3;
    const rows = Math.ceil(sectors.length / cols);

    sectors.forEach((sector, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        sectorCenters[sector] = {
            x: width * (col + 0.5) / cols,
            y: height * (row + 0.5) / rows
        };
    });

    // Scale for bubble sizes
    const marketCaps = stocks.filter(d => !d.isETF && d.marketCap > 0).map(d => d.marketCap);
    const radiusScale = d3.scaleSqrt()
        .domain([d3.min(marketCaps), d3.max(marketCaps)])
        .range([15, 55]);

    // Add radius to each stock
    stocks.forEach(d => {
        if (d.isETF || d.marketCap === 0) {
            d.radius = 20; // Uniform size for ETFs
        } else {
            d.radius = radiusScale(d.marketCap);
        }
    });

    // Create force simulation
    const simulation = d3.forceSimulation(stocks)
        .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.15))
        .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.15))
        .force('collide', d3.forceCollide(d => d.radius + 3).strength(1))
        .force('center', d3.forceCenter(width / 2, height / 2).strength(0.02));

    // Create bubble groups
    const bubbles = svg.selectAll('.bubble-group')
        .data(stocks)
        .join('g')
        .attr('class', 'bubble-group');

    // Add circles
    bubbles.append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector])
        .on('click', (event, d) => {
            onSelect(d.ticker);
        })
        .on('mouseover', (event, d) => {
            if (!d.isETF) {
                tooltip
                    .style('opacity', 1)
                    .html(`
                        <div class="ticker">${d.ticker}</div>
                        <div class="name">${d.name}</div>
                        <div class="sector">${d.sector}</div>
                    `);
            }
        })
        .on('mousemove', (event) => {
            tooltip
                .style('left', (event.pageX + 15) + 'px')
                .style('top', (event.pageY - 10) + 'px');
        })
        .on('mouseout', () => {
            tooltip.style('opacity', 0);
        });

    // Add labels
    bubbles.append('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => {
            const maxLen = d.ticker.length;
            const size = Math.min(d.radius * 1.5 / maxLen * 2, d.radius * 0.7);
            return Math.max(size, 8) + 'px';
        });

    // Update positions on tick
    simulation.on('tick', () => {
        bubbles.attr('transform', d => {
            // Keep bubbles within bounds
            d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
            d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
            return `translate(${d.x}, ${d.y})`;
        });
    });

    // Run simulation for a bit to stabilize
    for (let i = 0; i < 300; i++) simulation.tick();
    simulation.stop();

    // Final position update
    bubbles.attr('transform', d => `translate(${d.x}, ${d.y})`);
}

function createTable(stocks, onSelect) {
    const table = d3.select('#stock-table');
    const thead = table.append('thead');
    const tbody = table.append('tbody');

    // Header
    thead.append('tr')
        .selectAll('th')
        .data(['Ticker', 'Company Name', 'Sector', 'Market Cap'])
        .join('th')
        .text(d => d);

    // Sort stocks by market cap descending
    const sortedStocks = [...stocks].sort((a, b) => b.marketCap - a.marketCap);

    // Rows
    const rows = tbody.selectAll('tr')
        .data(sortedStocks)
        .join('tr')
        .attr('data-ticker', d => d.ticker)
        .on('click', (event, d) => {
            onSelect(d.ticker);
        });

    // Cells
    rows.selectAll('td')
        .data(d => [
            d.ticker,
            d.name,
            d.sector,
            formatMarketCap(d.marketCap)
        ])
        .join('td')
        .text(d => d);
}

function createLegend() {
    const legend = d3.select('#legend');

    Object.entries(sectorColors).forEach(([sector, color]) => {
        const item = legend.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', color);

        item.append('span')
            .text(sector);
    });
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', init);

